package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.*;
import com.fasterxml.jackson.databind.deser.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.KeyDeserializer;
import com.fasterxml.jackson.databind.deser.TypeDeserializer;
import com.fasterxml.jackson.databind.deser.impl.PropertyBasedCreator;
import com.fasterxml.jackson.databind.deser.impl.PropertyValueBuffer;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.std.MapDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.Set;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;

public class MapDeserializer_setIgnorableProperties_TriageGen2Test {

    private MapDeserializer deserializer;
    private JavaType mockMapType;
    private ValueInstantiator mockValueInstantiator;
    private KeyDeserializer mockKeyDeser;
    private JsonDeserializer<Object> mockValueDeser;
    private TypeDeserializer mockValueTypeDeser;

    @Before
    public void setUp() {
        mockMapType = mock(JavaType.class);
        mockValueInstantiator = mock(ValueInstantiator.class);
        mockKeyDeser = mock(KeyDeserializer.class);
        mockValueDeser = mock(JsonDeserializer.class);
        mockValueTypeDeser = mock(TypeDeserializer.class);

        deserializer = new MapDeserializer(
                mockMapType,
                mockValueInstantiator,
                mockKeyDeser,
                mockValueDeser,
                mockValueTypeDeser
        );
    }

    /**
     * Helper method to access the private field _ignorableProperties via reflection
     * for verification since the field is not public and has no getter.
     */
    @SuppressWarnings("unchecked")
    private Set<String> getIgnorableProperties() throws Exception {
        Field field = MapDeserializer.class.getDeclaredField("_ignorableProperties");
        field.setAccessible(true);
        return (Set<String>) field.get(deserializer);
    }

    @Test
    public void testSetIgnorableProperties_WithNull() throws Exception {
        // Act
        deserializer.setIgnorableProperties(null);

        // Assert
        assertNull("When input is null, _ignorableProperties should be null", getIgnorableProperties());
    }

    @Test
    public void testSetIgnorableProperties_WithEmptyArray() throws Exception {
        // Act
        deserializer.setIgnorableProperties(new String[0]);

        // Assert
        assertNull("When input is empty array, _ignorableProperties should be null", getIgnorableProperties());
    }

    @Test
    public void testSetIgnorableProperties_WithValidProperties() throws Exception {
        // Arrange
        String[] properties = {"prop1", "prop2", "prop3"};

        // Act
        deserializer.setIgnorableProperties(properties);

        // Assert
        Set<String> result = getIgnorableProperties();
        assertNotNull("Resulting set should not be null", result);
        assertEquals("Set size should match input array length", 3, result.size());
        assertTrue("Set should contain prop1", result.contains("prop1"));
        assertTrue("Set should contain prop2", result.contains("prop2"));
        assertTrue("Set should contain prop3", result.contains("prop3"));
    }

    @Test
    public void testSetIgnorableProperties_OverwriteExisting() throws Exception {
        // Arrange
        deserializer.setIgnorableProperties(new String[]{"old"});

        // Act
        deserializer.setIgnorableProperties(new String[]{"new"});

        // Assert
        Set<String> result = getIgnorableProperties();
        assertEquals(1, result.size());
        assertTrue(result.contains("new"));
        assertFalse(result.contains("old"));
    }
}

/**
 * Mocking ValueInstantiator as it is not a standard public class in the provided snippet 
 * but required for the constructor.
 */
abstract class ValueInstantiator {
    // Mocking structure to allow instantiation in tests
}
